package mz.bam.seeky.android;
import java.util.*;
public class TextSearchTest {
 static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);n++;System.out.println("PASS "+s);}
 public static void main(String[] args){List<TextSearch.Match> m=TextSearch.find("Ação, ACAO, acção.","acao",10,true,false);check(m.size()==2&&m.get(0).start==0&&m.get(0).end==4,"Portuguese accent folding returns original composed ranges");check(TextSearch.find("Ação ACAO","acao",10,false,false).size()==1,"accent-sensitive option remains available");String decomposed="ac\u0327a\u0303o";m=TextSearch.find(decomposed,"ação",10,true,false);check(m.size()==1&&m.get(0).end==decomposed.length(),"decomposed marks retain exact selection end");m=TextSearch.find("a\u0301!","a",10,true,true);check(m.size()==1&&m.get(0).end==2,"whole-word match includes trailing combining marks");check(TextSearch.find("ação ações reação ação_2", "acao",10,true,true).size()==1,"whole word excludes word interiors and underscores");m=TextSearch.find("📚 ação 📚","acao",10,true,true);check(m.size()==1&&m.get(0).start==3&&m.get(0).end==7,"emoji preceding match preserves UTF-16 offsets");check(TextSearch.find("x x x","x",2,true,false).size()==2,"result cap enforced");check(TextSearch.find("á","\u0301",10,true,false).isEmpty(),"query containing only ignored marks cannot match empty text");check(TextSearch.find("abc","",10,true,false).isEmpty(),"empty query rejected");check(TextSearch.find("abc","a",0,true,false).isEmpty(),"zero cap returns no matches");check(TextSearch.find("ÁGUA água","água",10,false,false).size()==2,"Unicode case-insensitive search preserved");check(TextSearch.find("um-dois","dois",10,true,true).size()==1,"punctuation is a word boundary");m=TextSearch.find("éé","ee",10,true,false);check(m.size()==1&&m.get(0).end==2,"multiple folded accents do not shift offsets");JsonBudget.check("{\"text\":\"[{}]\"}",4,3);check(true,"JSON budget ignores structures inside quoted text");try{JsonBudget.check("[[[[[[[[[0]]]]]]]]]",8,30);throw new AssertionError();}catch(IllegalArgumentException e){check(true,"JSON nesting guard rejects deep imported structures");}try{JsonBudget.check("[{}",8,30);throw new AssertionError();}catch(IllegalArgumentException e){check(true,"JSON guard rejects truncated containers");}System.out.println("PASS "+n+" mapped-text search and JSON-budget checks");}
}
